import React, { useState } from "react";

import PetCard from "./petCard";

export default function ourPetsSection(props) {
  
  return (
    <div className="container mt-4">
          <div className="row">
            <div className="col-md-3">
              <PetCard title="Card 1" description="This is card 1"/>
            </div>
            <div className="col-md-3">
              <PetCard title="Card 2" description="This is card 2" />
            </div>
            <div className="col-md-3">
              <PetCard title="Card 3" description="This is card 3" />
            </div>
            <div className="col-md-3">
              <PetCard title="Card 4" description="This is card 4"/>
            </div>
          </div>
        </div>
  );
}
